 if(gBehind>.02){const pts=[fp(st,fr,m.u-.45,m.v),fp(st,fr,lerp(m.u-.45,sr.u,.5),m.v),fp(st,fr,sr.u+.55,m.v)];cased(s,pts,w,seed,{dash:w*2.5,progress:gBehind});if(gBehind>.95)casedHead(s,pts,w*2.6,seed+1);}
