// ---------------- seven-segment digits (the arena board, the group results) ----------------
const SEG:Record<string,number[]>={'0':[0,1,2,4,5,6],'1':[2,5],'2':[0,2,3,4,6],'3':[0,2,3,5,6],'4':[1,2,3,5],'5':[0,1,3,5,6],'6':[0,1,3,4,5,6],'7':[0,2,5],'8':[0,1,2,3,4,5,6],'9':[0,1,2,3,5,6]};
function digit(p:Path2D,ch:string,x:number,y:number,h:number){const w=h*.55,t=h*.13,segs:[number,number,number,number][]=[[0,0,w,t],[0,0,t,h/2],[w-t,0,t,h/2],[0,h/2-t/2,w,t],[0,h/2,t,h/2],[w-t,h/2,t,h/2],[0,h-t,w,t]];for(const k of SEG[ch]??[]){const[a,b,c,d]=segs[k];p.rect(x+a,y+b,c,d);}}
/** width of a seven-segment string */
const segW=(str:string,h:number)=>[...str].reduce((a,c)=>a+(c===':'?h*.3:c==='-'?h*.5:h*.55)+h*.2,-h*.2);
/** a seven-segment string starting at x; each character's left edge is returned (for rings round the zeros) */
function segText(p:Path2D,str:string,x:number,y:number,h:number){const at:number[]=[];let cx=x;for(const c of str){at.push(cx);if(c===':'){p.rect(cx+h*.08,y+h*.25,h*.14,h*.14);p.rect(cx+h*.08,y+h*.62,h*.14,h*.14);cx+=h*.3+h*.2;}else if(c==='-'){p.rect(cx,y+h*.45,h*.5,h*.12);cx+=h*.5+h*.2;}else{digit(p,c,cx,y,h);cx+=h*.55+h*.2;}}return at;}
/** a navy panel with yellow digits (glow knocks the digits to paper for a flash) */
function segPanel(s:Sheet,cx:number,top:number,str:string,h:number,seed:number,glow=0,tabs?:[string,string]){
 const W=segW(str,h)+h*1.4,H=h*1.5,box=polyPath(handCut([[cx-W/2,top],[cx+W/2,top],[cx+W/2,top+H],[cx-W/2,top+H]],seed,3,80),true);s.knockout(box);s.fill(K,box);
 if(tabs){const p1=new Path2D(),p2=new Path2D();p1.rect(cx-W/2+h*.2,top+h*.08,W*.16,h*.1);p2.rect(cx+W/2-h*.2-W*.16,top+h*.08,W*.16,h*.1);s.fill(tabs[0],p1);s.fill(tabs[1],p2);}
 const lit=new Path2D(),at=segText(lit,str,cx-segW(str,h)/2,top+h*.3,h);s.knockout(lit);s.fill(Y,lit,1-.75*Math.min(1,glow));return{at,W,H};
}

