 // floor diagrams first (under the players)
 if(cues.mate!==undefined){const g=easeOutBack(sm(cues.mate,cues.mate+.35,tt))*(1-sm(cues.fade-.3,cues.fade,tt));if(g>.02){const[X,Z]=toStage(fr,mate.u,mate.v);floorDashRing(s,st,K,X,Z,.7,18,190,g);floorDashRing(s,st,R,X,Z,.7,11,191,g);}}
 if(cues.goes!==undefined){const ca=sm(cues.goes,cues.goes+.4,tt,easeOut)*(1-sm(T.meet-.1,T.meet+.3,q));if(ca>.02){const a0=mate.u+.5,a1=Math.max(a0+.3,att.u-.7),pts=[fp(st,fr,a0,mate.v),fp(st,fr,(a0+a1)/2,mate.v+.1),fp(st,fr,a1,PV)];cased(s,pts,12,201,{dash:38,progress:ca});if(ca>.9)casedHead(s,pts,34,202);}}
 if(cues.waits!==undefined){const g=easeOutBack(sm(cues.waits,cues.waits+.35,tt));serRing(s,st,fr,ser,g,205,.8);}
 const gb=sm(cues.behind,cues.behind+.5,tt,easeOut)*(1-sm(cues.fade-.3,cues.fade,tt)),gs=sm(cues.side,cues.side+.5,tt,easeOut)*(1-sm(cues.fade-.3,cues.fade,tt));
 if(gb>.02||gs>.02){const mm={...mate,u:Math.min(mate.u,PU),v:PV},sr={...ser,u:SC,v:SV};coverL(s,st,fr,mm,sr,gb,gs,210,o.arena==='end'?24:16);}
 // "gets past": a red arrow of the attacker's cut inside; "free run" (ch4): a red dashed route to goal that stops at Sergeev
 if(cues.past!==undefined){const g=sm(cues.past,cues.past+.5,tt,easeOut)*(1-sm(cues.there+.4,cues.there+.8,tt));if(g>.02){const pts=[fp(st,fr,PU+.9,AV0+.15),fp(st,fr,PU-.4,lerp(AV0,AV,.6)),fp(st,fr,UH+.2,AV)];dashed(s,R,pts,15,215,{dash:40,progress:g});if(g>.9)arrowHead(s,R,pts,40,216);}}
  const items:Item[]=[
  {z:depth(fr,att),draw:()=>athlete(s,st,fr,cv.att,q,DEMO_A,{detail:o.detail,smear:q>T.past-.1&&q<T.cutEnd?o.smear*.6:0})},
  {z:depth(fr,mate),draw:()=>athlete(s,st,fr,cv.mate,q,DEMO_T,{detail:o.detail,smear:q>T.past&&q<T.past+.5?Math.min(.1,o.smear):0})},
  {z:depth(fr,ser)-.001,draw:()=>athlete(s,st,fr,cv.ser,q,SERGEEV,{detail:o.detail,band:true,smear:q>T.step&&q<T.hit+.1?o.smear:0})},
  {z:depth(fr,b)-.002,draw:()=>{drawBallL(s,st,fr,b,211,9);if(q>=T.hit&&q<T.hit+.4){const p=fp(st,fr,b.u,b.v,.15);sparkBurst(s,Y,p[0],p[1],100,{n:9,seed:212,g:easeOut(sm(T.hit,T.hit+.25,q))});}}},
 ];
 items.sort((a,c)=>c.z-a.z).forEach(it=>it.draw());
 // "free run" (ch4): the attacker's route to goal, a red dashed arrow drawn over the players — it stops at Sergeev and is crossed out
 if(cues.free!==undefined){const g=sm(cues.free,cues.free+.5,tt,easeOut)*(1-sm(cues.clean+.6,cues.clean+1,tt));if(g>.02){const a0=Math.max(att.u-.3,ser.u+1),pts=[fp(st,fr,a0,AV,.25),fp(st,fr,lerp(a0,ser.u+.45,.5),AV,.3),fp(st,fr,ser.u+.45,AV,.25)];dashed(s,R,pts,20,217,{dash:44,progress:g});
  const cx=easeOutBack(sm(cues.free+.45,cues.free+.75,tt))*(1-sm(cues.clean+.6,cues.clean+1,tt));if(cx>.02){const p=pts[2],r=kAt(st,depth(fr,ser))*.28*cx;crossAt(s,p,r,218);}}}
 // "already there": the low bracket beside him
