const seq3=(t:number)=>key(t,mono([[0,T2.meet-.3],[C3.behind,T2.meet+.4],[C3.side,T2.past-.6],[C3.ready,T2.past+.3],[C3.ready+1.4,T2.hit+.05],[C3.end,T2.out+.9]]),linear);
